18	
19	// ErrParseFailed is returned by Semantic when any .tf file fails to
20	// parse. Callers map this to exit code 5.
21	var ErrParseFailed = errors.New("hcl parse failed")
22	
23	// blockEntry pairs an HCL block with the source bytes of its file so
24	// that blockHash can read actual expression text rather than byte offsets.
25	type blockEntry struct {
26		block *hclsyntax.Block
27		src   []byte
28	}
29	
30	// ModuleSummary aggregates the named HCL blocks of interest from every
31	// .tf file in a module. Maps are keyed by a stable identifier
32	// (resource: "type.name", variable: name, etc.).
33	type ModuleSummary struct {
34		Resources map[string]blockEntry
35		Variables map[string]blockEntry
36		Outputs   map[string]blockEntry
37		Providers map[string]blockEntry
38		Locals    map[string]blockEntry
39		Data      map[string]blockEntry
40		Modules   map[string]blockEntry
41	}
42	
43	// Semantic produces SemanticChange entries by parsing every .tf file in
44	// each archive into a ModuleSummary and diffing summaries.
45	func Semantic(a, b archive.Module) ([]SemanticChange, error) {
46		sa, err := summarize(a)
47		if err != nil {
48			return nil, err
49		}
50		sb, err := summarize(b)
51		if err != nil {
52			return nil, err
53		}
54		var out []SemanticChange
55		out = append(out, diffMap("resource", sa.Resources, sb.Resources)...)
56		out = append(out, diffMap("variable", sa.Variables, sb.Variables)...)
57		out = append(out, diffMap("output", sa.Outputs, sb.Outputs)...)
58		out = append(out, diffMap("provider", sa.Providers, sb.Providers)...)
59		out = append(out, diffMap("locals", sa.Locals, sb.Locals)...)
60		out = append(out, diffMap("data", sa.Data, sb.Data)...)
61		out = append(out, diffMap("module", sa.Modules, sb.Modules)...)
62		sort.SliceStable(out, func(i, j int) bool {
63			if out[i].Kind != out[j].Kind {
64				return out[i].Kind < out[j].Kind
65			}
66			return out[i].Name < out[j].Name
67		})
68		return out, nil
69	}
70	
71	func summarize(m archive.Module) (ModuleSummary, error) {
72		s := ModuleSummary{
73			Resources: map[string]blockEntry{},
74			Variables: map[string]blockEntry{},
75			Outputs:   map[string]blockEntry{},
76			Providers: map[string]blockEntry{},
77			Locals:    map[string]blockEntry{},
78			Data:      map[string]blockEntry{},
79			Modules:   map[string]blockEntry{},
80		}
81		parser := hclparse.NewParser()
82		for path, body := range m.Files {
83			if !strings.HasSuffix(path, ".tf") {
84				continue
85			}
86			file, diags := parser.ParseHCL(body, path)
87			if diags.HasErrors() {
88				return ModuleSummary{}, fmt.Errorf("%w: %s: %s", ErrParseFailed, path, diags.Error())
89			}
90			syntaxBody, ok := file.Body.(*hclsyntax.Body)
91			if !ok {
92				return ModuleSummary{}, fmt.Errorf("%w: %s: unexpected body type", ErrParseFailed, path)
93			}
94			for _, blk := range syntaxBody.Blocks {
95				key, target := classify(blk, &s)
96				if target == nil {
97					continue
98				}
99				target[key] = blockEntry{block: blk, src: body}
100			}
101		}
102		return s, nil
103	}
104	
105	func classify(blk *hclsyntax.Block, s *ModuleSummary) (string, map[string]blockEntry) {
106		switch blk.Type {
107		case "resource":
108			if len(blk.Labels) != 2 {
109				return "", nil
110			}
111			return blk.Labels[0] + "." + blk.Labels[1], s.Resources
112		case "data":
113			if len(blk.Labels) != 2 {
114				return "", nil
115			}
116			return blk.Labels[0] + "." + blk.Labels[1], s.Data
117		case "module":
118			if len(blk.Labels) != 1 {
119				return "", nil
120			}
121			return blk.Labels[0], s.Modules
122		case "variable":
123			if len(blk.Labels) != 1 {
124				return "", nil
125			}
126			return blk.Labels[0], s.Variables
127		case "output":
128			if len(blk.Labels) != 1 {
129				return "", nil
130			}
131			return blk.Labels[0], s.Outputs
132		case "provider":
133			if len(blk.Labels) != 1 {
134				return "", nil
135			}
136			return blk.Labels[0], s.Providers
137		case "locals":
138			// `locals` has no labels and may appear in multiple files;
139			// distinguish by source range so we don't collide.
140			return blk.Range().Filename + "#" + fmt.Sprint(blk.Range().Start.Line), s.Locals
141		}
142		return "", nil
143	}
144	
145	func diffMap(kind string, a, b map[string]blockEntry) []SemanticChange {
146		var out []SemanticChange
147		for name, ae := range a {
148			be, ok := b[name]
149			if !ok {
150				out = append(out, SemanticChange{Kind: kind, Name: name, Status: StatusRemoved})
151				continue
152			}
153			if blockHash(ae) != blockHash(be) {
154				out = append(out, SemanticChange{Kind: kind, Name: name, Status: StatusModified})
155			}
156		}
157		for name := range b {
158			if _, ok := a[name]; !ok {
159				out = append(out, SemanticChange{Kind: kind, Name: name, Status: StatusAdded})
160			}
161		}
162		return out
163	}
164	
165	// blockHash digests the content of a block using actual source bytes for
166	// attribute expressions, recursing into nested blocks so changes anywhere
167	// in the block tree (e.g., lifecycle { prevent_destroy = X }, dynamic,
168	// provisioner) shift the hash.
169	func blockHash(e blockEntry) string {
170		h := sha256.New()
171		hashBlock(h, e.block, e.src)
172		return hex.EncodeToString(h.Sum(nil))
173	}
174	
175	// hashBlock writes a block's labels, sorted attribute key + source text
176	// pairs, and each nested block's (type, recursive hash) into h.
177	func hashBlock(h hash.Hash, blk *hclsyntax.Block, src []byte) {
178		h.Write([]byte(strings.Join(blk.Labels, "|")))
179		h.Write([]byte{0})
180		keys := make([]string, 0, len(blk.Body.Attributes))
181		for k := range blk.Body.Attributes {
182			keys = append(keys, k)
183		}
184		sort.Strings(keys)
185		for _, k := range keys {
186			attr := blk.Body.Attributes[k]
187			h.Write([]byte(k))
188			h.Write([]byte{0})
189			h.Write([]byte(exprText(src, attr.Expr.Range())))
190			h.Write([]byte{0})
191		}
192		for _, nested := range blk.Body.Blocks {
193			h.Write([]byte(nested.Type))
194			h.Write([]byte{0})
195			hashBlock(h, nested, src)
196			h.Write([]byte{0})
197		}
198	}
199	
200	// exprText returns the actual source bytes of an expression's range.
201	func exprText(src []byte, r hcl.Range) string {
202		if r.End.Byte > len(src) || r.Start.Byte > r.End.Byte {
203			return fmt.Sprintf("%d:%d", r.Start.Byte, r.End.Byte)
204		}
205		return string(src[r.Start.Byte:r.End.Byte])
206	}
