func TestSemanticLocalsLineShiftIsNotAChange(t *testing.T) {
	// Same local definition, different surrounding whitespace pushes
	// the locals block to a different line. Must NOT report changes.
	a := mkArchive(map[string]string{"main.tf": `
locals {
  region = "us-east-1"
}
`})
	b := mkArchive(map[string]string{"main.tf": `
# new comment

variable "x" {}

locals {
  region = "us-east-1"
}
`})
	changes, err := Semantic(a, b)
	if err != nil {
		t.Fatalf("Semantic: %v", err)
	}
	for _, c := range changes {
		if c.Kind == "locals" {
			t.Errorf("unexpected locals change after line shift: %+v", c)
		}
	}
}

